<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='checkout'){
 $items=json_decode($_POST['cart_json']??'[]',true);$customerId=(int)($_POST['customer_id']??0)?:null;$method=$_POST['payment_method']??'Cash';$paid=max(0,(float)($_POST['paid_amount']??0));$allowed=['Cash','PhonePe/UPI','Card','Due'];
 if(!is_array($items)||!count($items)||!in_array($method,$allowed,true)){flash('Choose at least one valid item and payment method.','error');redirect('pos.php');}
 try{$pdo->beginTransaction();$subtotal=0;$valid=[];foreach($items as $item){$id=(int)($item['id']??0);$qty=max(1,min(999,(int)($item['qty']??1)));$st=$pdo->prepare("SELECT * FROM products WHERE id=? AND active=1 FOR UPDATE");$st->execute([$id]);$p=$st->fetch();if(!$p||$p['stock_qty']<$qty)throw new Exception('Insufficient stock for an item in your cart.');$line=$p['selling_price']*$qty;$subtotal+=$line;$valid[]=['product'=>$p,'qty'=>$qty,'line'=>$line];}
 $total=$subtotal;$paid=min($paid,$total);if($method!=='Due' && $paid==0)$paid=$total;if($method==='Due')$paid=min($paid,$total);$balance=$total-$paid;$invoice='AQ-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
 $st=$pdo->prepare("INSERT INTO sales(invoice_no,customer_id,user_id,subtotal,total,paid_amount,balance,payment_method) VALUES(?,?,?,?,?,?,?,?)");$st->execute([$invoice,$customerId,current_user()['id'],$subtotal,$total,$paid,$balance,$method]);$saleId=(int)$pdo->lastInsertId();
 foreach($valid as $v){$p=$v['product'];$pdo->prepare("INSERT INTO sale_items(sale_id,product_id,product_name,qty,unit_price,cost_price,line_total) VALUES(?,?,?,?,?,?,?)")->execute([$saleId,$p['id'],$p['name'],$v['qty'],$p['selling_price'],$p['cost_price'],$v['line']]);$pdo->prepare("UPDATE products SET stock_qty=stock_qty-? WHERE id=?")->execute([$v['qty'],$p['id']]);}
 $pdo->commit();flash('Sale completed. Invoice '.$invoice);redirect('invoice.php?id='.$saleId);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof PDOException?'Unable to complete sale. Check database configuration.':$e->getMessage(),'error');redirect('pos.php');}
}
$products=$pdo->query("SELECT id,name,category,selling_price,stock_qty FROM products WHERE active=1 AND stock_qty>0 ORDER BY category,name")->fetchAll();$customers=$pdo->query("SELECT id,name,phone FROM customers ORDER BY name")->fetchAll();layout_start('Point of sale','pos');?>
<div class="pos-layout"><section class="panel product-picker"><div class="panel-head"><div><h3>Choose products</h3><p class="muted">Tap an item to add it to the bill.</p></div><span class="badge"><?=count($products)?> available</span></div><input id="productSearch" class="search-input" placeholder="⌕ Search tubes, caps, goggles…"><div class="product-grid" id="productGrid"><?php foreach($products as $p):?><button type="button" class="product-tile" data-id="<?=$p['id']?>" data-name="<?=h($p['name'])?>" data-category="<?=h($p['category'])?>" data-price="<?=$p['selling_price']?>" data-stock="<?=$p['stock_qty']?>"><span class="product-art"><?=h(strtoupper(substr($p['category'],0,1)))?></span><span class="product-info"><b><?=h($p['name'])?></b><small><?=h($p['category'])?> · <?=$p['stock_qty']?> in stock</small><strong><?=money($p['selling_price'])?></strong></span><span class="add-mark">＋</span></button><?php endforeach;?></div><?php if(!$products):?><div class="empty large">No stock available. Add products in Inventory first.</div><?php endif;?></section><section class="panel cart-panel"><div class="panel-head"><div><h3>Current bill</h3><p class="muted">AquaDesk checkout</p></div><span class="cart-count" id="cartCount">0</span></div><div id="cartItems" class="cart-items"><div class="empty">Your cart is empty.<br>Choose a product to begin.</div></div><div class="checkout-form"><label>Customer<select id="customerSelect"><option value="">Walk-in customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?><?= $c['phone']?' · '.h($c['phone']):''?></option><?php endforeach;?></select></label><div class="total-row"><span>Subtotal</span><b id="subtotal">₹0.00</b></div><div class="total-row grand"><span>Total due</span><b id="total">₹0.00</b></div><form method="post" id="checkoutForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="checkout"><input type="hidden" name="cart_json" id="cartJson"><input type="hidden" name="customer_id" id="customerId"><label>Payment method<select name="payment_method" id="paymentMethod"><option>Cash</option><option>PhonePe/UPI</option><option>Card</option><option>Due</option></select></label><label>Amount received (₹)<input type="number" name="paid_amount" id="paidAmount" min="0" step=".01" value="0"></label><button class="btn primary full" id="completeSale" type="submit" disabled>Complete sale →</button><p class="tiny muted">Stock is reduced when the sale is saved.</p></form></div></section></div><script>window.POS_CSRF=<?=json_encode(csrf_token())?>;</script><script src="assets/js/pos.js"></script><?php layout_end();?>
